package dev.pocketengine.features.workspace;

import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.local.project.ProjectSources;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;

/** Own disk fixtures only. No application DB, account, provider or external path. */
public final class OwnerDataArchivePrimitiveTest {
    private static String id(){return UUID.randomUUID().toString();}
    private static String sha(byte[] bytes)throws Exception{return ProjectSources.sha256(bytes);}
    private static OwnerBackupArchive.ObjectBytes object(byte[] bytes)throws Exception{return new OwnerBackupArchive.ObjectBytes(sha(bytes),bytes.length,()->new ByteArrayInputStream(bytes));}
    @Test public void portableArchiveReopensExactBinaryAndSectionWithoutExtractingPaths()throws Exception {
        Path root=Files.createTempDirectory("owner-archive-roundtrip-");byte[] binary={0,1,(byte)255,10,0};JSONObject section=new JSONObject().put("format","test.projects.v1").put("name","中文工程😀").put("object",sha(binary));var json=OwnerBackupArchive.ObjectBytes.json(section);var bin=object(binary);File zip=root.resolve("snapshot.zip").toFile();var selected=OwnerBackupArchive.create(zip,Map.of(json.sha256,json,bin.sha256,bin),Map.of("projects",json.sha256),new RunControl());
        var cold=OwnerBackupArchive.verify(zip,new RunControl());assertEquals(selected.sha256(),cold.sha256());assertEquals("中文工程😀",cold.section("projects",new RunControl()).getString("name"));assertArrayEquals(binary,cold.object(bin.sha256,new RunControl()));assertFalse(cold.metadata().getBoolean("restoresTasksOrGrants"));assertFalse(cold.metadata().getBoolean("restoresAccountCredentials"));assertTrue(cold.metadata().getBoolean("userContentMayContainSensitiveData"));assertEquals(1,root.toFile().list().length);ByteArrayOutputStream export=new ByteArrayOutputStream();assertEquals(zip.length(),cold.export(export,new RunControl()));assertArrayEquals(Files.readAllBytes(zip.toPath()),export.toByteArray());
    }
    @Test public void badObjectHashCancellationAndArchiveReplacementNeverProduceVerifiedPartial()throws Exception {
        Path root=Files.createTempDirectory("owner-archive-reject-");byte[] value="old".getBytes(StandardCharsets.UTF_8);var valid=object(value);JSONObject section=new JSONObject().put("x",valid.sha256);var json=OwnerBackupArchive.ObjectBytes.json(section);File wrong=root.resolve("wrong.zip").toFile();var lie=new OwnerBackupArchive.ObjectBytes("a".repeat(64),value.length,()->new ByteArrayInputStream(value));assertThrows(Exception.class,()->OwnerBackupArchive.create(wrong,Map.of(lie.sha256,lie),Map.of("projects",lie.sha256),new RunControl()));assertFalse(wrong.exists());RunControl cancelled=new RunControl();cancelled.cancel();File stopped=root.resolve("stopped.zip").toFile();assertThrows(Exception.class,()->OwnerBackupArchive.create(stopped,Map.of(json.sha256,json),Map.of("projects",json.sha256),cancelled));assertFalse(stopped.exists());File zip=root.resolve("actual.zip").toFile();var selected=OwnerBackupArchive.create(zip,Map.of(json.sha256,json,valid.sha256,valid),Map.of("projects",json.sha256),new RunControl());Files.writeString(zip.toPath(),"replaced");assertThrows(Exception.class,()->selected.object(valid.sha256,new RunControl()));assertThrows(Exception.class,()->OwnerBackupArchive.verify(zip,new RunControl()));
    }
    @Test public void malformedRawZipNameUnknownFieldAndDeepOrBrokenUnicodeAreRejected()throws Exception {
        Path root=Files.createTempDirectory("owner-archive-shape-");File zip=root.resolve("outside.zip").toFile();try(var out=new java.util.zip.ZipOutputStream(new FileOutputStream(zip))){out.putNextEntry(new java.util.zip.ZipEntry("../manifest.json"));out.write("{}".getBytes(StandardCharsets.UTF_8));out.closeEntry();}assertThrows(Exception.class,()->OwnerBackupArchive.verify(zip,new RunControl()));assertFalse(root.resolve("manifest.json").toFile().exists());String tooDeep="{\"x\":"+"[".repeat(33)+"0"+"]".repeat(33)+"}";assertThrows(Exception.class,()->OwnerBackupArchive.parseObject(tooDeep.getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->OwnerBackupArchive.parseObject("{\"x\":\"\\ud800\"}".getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->OwnerBackupArchive.parseObject(new byte[]{(byte)0xc3,0x28}));assertEquals("😀",OwnerBackupArchive.parseObject("{\"x\":\"\\ud83d\\ude00\"}".getBytes(StandardCharsets.UTF_8)).getString("x"));var object=OwnerBackupArchive.ObjectBytes.json(new JSONObject().put("x",1));assertThrows(Exception.class,()->OwnerBackupArchive.create(root.resolve("unknown.zip").toFile(),Map.of(object.sha256,object),Map.of("secrets",object.sha256),new RunControl()));
    }
    @Test public void projectArchiveKeepsRetainedHistoryAndTombstoneButAssignsNewProjectAndRevisions()throws Exception {
        Path root=Files.createTempDirectory("owner-project-archive-");VersionedWorkspace old=new VersionedWorkspace(root.resolve("old").toFile());String project=old.create("原工程").getString("id");var one=old.writeBytes(project,"data.bin",new byte[]{0,1,2},0,"absent");var two=old.writeBytes(one,new byte[]{0,3,(byte)255});var deleted=old.delete(two);old.write(project,"src/main.ts","export const amount = 45;",0,false);JSONObject archive=old.ownerProjectArchive(project,new RunControl());String digest=ProjectSources.digest(archive),action=id();VersionedWorkspace target=new VersionedWorkspace(root.resolve("new").toFile());JSONObject missing=target.queryOwnerProjectArchive(archive,action,digest);assertFalse(missing.getBoolean("found"));assertEquals("unknown",missing.getString("status"));assertEquals(0,target.projects().length());JSONObject restored=target.restoreOwnerProjectArchive(archive,action,digest,new RunControl());String newProject=restored.getString("id");assertNotEquals(project,newProject);var current=target.snapshot(newProject,"data.bin",0);assertTrue(current.tombstone);assertEquals(3,current.version);assertNotEquals(deleted.revisionId,current.revisionId);assertArrayEquals(one.bytes(),target.snapshot(newProject,"data.bin",1).bytes());assertArrayEquals(two.bytes(),target.snapshot(newProject,"data.bin",2).bytes());assertNotEquals(one.revisionId,target.snapshot(newProject,"data.bin",1).revisionId);VersionedWorkspace cold=new VersionedWorkspace(root.resolve("new").toFile());assertEquals(newProject,cold.queryOwnerProjectArchive(archive,action,digest).getString("id"));cold.restoreOwnerProjectArchive(archive,action,digest,new RunControl());assertEquals(1,cold.projects().length());assertFalse(restored.getJSONObject("archiveImport").getBoolean("executionAuthorityRestored"));assertThrows(Exception.class,()->cold.restoreOwnerProjectArchive(archive,action,"b".repeat(64),new RunControl()));
    }
    @Test public void restoredFixedBinaryAndDeletionArtifactsUseSameCatalogWithoutOldTaskAuthority()throws Exception {
        Path root=Files.createTempDirectory("owner-artifact-archive-");VersionedWorkspace old=new VersionedWorkspace(root.resolve("old").toFile());String project=old.create("原件").getString("id"),oldTask=id();var original=old.writeBytes(project,"image.bin",new byte[]{0,9,(byte)255},0,"absent");WorkspaceArtifacts catalog=new WorkspaceArtifacts(root.resolve("old-artifacts").toFile(),old);var binary=catalog.freezeFile(original,id(),oldTask,id());var tombstone=catalog.freezeFile(old.delete(original),id(),oldTask,id());JSONObject bytesArchive=catalog.ownerFileArchive(binary.artifactId,binary.sha256),deleteArchive=catalog.ownerFileArchive(tombstone.artifactId,"absent");JSONObject projectArchive=old.ownerProjectArchive(project,new RunControl());String action=id(),sectionDigest="c".repeat(64);VersionedWorkspace target=new VersionedWorkspace(root.resolve("new").toFile());String nextProject=target.restoreOwnerProjectArchive(projectArchive,action,sectionDigest,new RunControl()).getString("id");WorkspaceArtifacts next=new WorkspaceArtifacts(root.resolve("new-artifacts").toFile(),target);JSONObject a=next.restoreOwnerFileArchive(bytesArchive,catalog.bytes(binary),nextProject,action,sectionDigest,new RunControl()),b=next.restoreOwnerFileArchive(deleteArchive,new byte[0],nextProject,action,sectionDigest,new RunControl());var fixed=next.reference(a.getString("id"),binary.sha256);var removed=next.reference(b.getString("id"),"absent");assertArrayEquals(new byte[]{0,9,(byte)255},next.bytes(fixed));assertNotEquals(binary.artifactId,fixed.artifactId);assertFalse(fixed.json().has("taskId"));assertTrue(removed.tombstone);assertThrows(Exception.class,()->next.bytes(removed));assertThrows(Exception.class,()->next.restoreOwnerFileArchive(bytesArchive,new byte[]{7},nextProject,id(),sectionDigest,new RunControl()));WorkspaceArtifacts cold=new WorkspaceArtifacts(root.resolve("new-artifacts").toFile(),target);assertEquals(fixed.artifactId,cold.queryOwnerFileArchive(bytesArchive,nextProject,action,sectionDigest).getString("id"));assertEquals(2,cold.list(nextProject).length());assertThrows(Exception.class,()->cold.queryOwnerFileArchive(bytesArchive,nextProject,action,"d".repeat(64)));
    }
    @Test public void fullProjectCapacityAndInvalidHistoryDoNotOverwriteExistingProject()throws Exception {
        Path root=Files.createTempDirectory("owner-project-capacity-");VersionedWorkspace source=new VersionedWorkspace(root.resolve("source").toFile());String original=source.create("来源").getString("id");source.write(original,"one.txt","one",0,false);JSONObject archive=source.ownerProjectArchive(original,new RunControl());VersionedWorkspace target=new VersionedWorkspace(root.resolve("target").toFile());for(int n=0;n<20;n++)target.create("保留"+n);assertThrows(Exception.class,()->target.restoreOwnerProjectArchive(archive,id(),ProjectSources.digest(archive),new RunControl()));assertEquals(20,target.projects().length());JSONObject bad=new JSONObject(archive.toString());bad.getJSONArray("records").getJSONObject(0).getJSONArray("history").getJSONObject(0).put("sha256","0".repeat(64));assertThrows(Exception.class,()->VersionedWorkspace.checkedOwnerProjectArchiveForHost(bad));assertEquals(20,target.projects().length());
    }
}
